"""More work for the board: every category gets a full set. Each task needs a person because the answer is not in the
text: a call to make, a place to stand in, a thing to hold up to the camera, or a question that only several people's
preference can settle. United States only."""

from __future__ import annotations

CODE = " Write the capture code shown on your task on paper and keep it in every shot."


WRITE = "What the task asked you to report, typed out: the figures, names, hours or words you can see, and anything else it asked for"


def _do(cat: str, title: str, instructions: str, minutes: int, proof: str = "text", location: str = "Remote", geo: tuple[float, float] | None = None, url: str | None = None, acceptance: str = "", difficulty: str = "medium", write: str | None = None) -> dict:
    payload: dict = {"category": cat, "instructions": instructions + (CODE if proof == "photos" else ""), "proof": proof}
    if proof == "photos":
        payload["write"] = write or WRITE  # a photo alone is never enough: the person types what it shows
    if geo:
        payload["geo"] = {"lat": geo[0], "lng": geo[1]}
    if url:
        payload["url"] = url
    return {"type": "do", "title": title, "location": location, "effortMinutes": minutes, "difficulty": difficulty, "acceptance": acceptance or ("Photos taken now with the code in the shot, the subject readable, and what they show typed out" if proof == "photos" else "Specific, first-hand, and complete for what was asked"), "payload": payload, "timeLimitSeconds": 1800}


def _choose(cat: str, title: str, question: str, options: list[str], workers: int = 3) -> dict:
    return {"type": "choose", "title": title, "location": "Remote", "effortMinutes": 1, "difficulty": "easy", "workers": workers, "payload": {"category": cat, "question": question, "options": options}}


